macro_rules! deps {
    () => {
        NFA!();
        DFA!();
    };
}

macro_rules! Repr {
    () => {
        deps!();
        # [doc = " Repr is a read-only view into the representation of a DFA state."] # [doc = ""] # [doc = " Primarily, a Repr is how we achieve DRY: we implement decoding the format"] # [doc = " in one place, and then use a Repr to implement the various methods on the"] # [doc = " public state types."] # [doc = ""] # [doc = " The format is as follows:"] # [doc = ""] # [doc = " The first three bytes correspond to bitsets."] # [doc = ""] # [doc = " Byte 0 is a bitset corresponding to miscellaneous flags associated with the"] # [doc = " state. Bit 0 is set to 1 if the state is a match state. Bit 1 is set to 1"] # [doc = " if the state has pattern IDs explicitly written to it. (This is a flag that"] # [doc = " is not meant to be set by determinization, but rather, is used as part of"] # [doc = " an internal space-saving optimization.) Bit 2 is set to 1 if the state was"] # [doc = " generated by a transition over a \"word\" byte. (Callers may not always set"] # [doc = " this. For example, if the NFA has no word boundary assertion, then needing"] # [doc = " to track whether a state came from a word byte or not is superfluous and"] # [doc = " wasteful.) Bit 3 is set to 1 if the state was generated by a transition"] # [doc = " from a `\\r` (forward search) or a `\\n` (reverse search) when CRLF mode is"] # [doc = " enabled."] # [doc = ""] # [doc = " Bytes 1..5 correspond to the look-behind assertions that were satisfied"] # [doc = " by the transition that created this state. (Look-ahead assertions are not"] # [doc = " tracked as part of states. Instead, these are applied by re-computing the"] # [doc = " epsilon closure of a state when computing the transition function. See"] # [doc = " `next` in the parent module.)"] # [doc = ""] # [doc = " Bytes 5..9 correspond to the set of look-around assertions (including both"] # [doc = " look-behind and look-ahead) that appear somewhere in this state's set of"] # [doc = " NFA state IDs. This is used to determine whether this state's epsilon"] # [doc = " closure should be re-computed when computing the transition function."] # [doc = " Namely, look-around assertions are \"just\" conditional epsilon transitions,"] # [doc = " so if there are new assertions available when computing the transition"] # [doc = " function, we should only re-compute the epsilon closure if those new"] # [doc = " assertions are relevant to this particular state."] # [doc = ""] # [doc = " Bytes 9..13 correspond to a 32-bit native-endian encoded integer"] # [doc = " corresponding to the number of patterns encoded in this state. If the state"] # [doc = " is not a match state (byte 0 bit 0 is 0) or if it's only pattern ID is"] # [doc = " PatternID::ZERO, then no integer is encoded at this position. Instead, byte"] # [doc = " offset 3 is the position at which the first NFA state ID is encoded."] # [doc = ""] # [doc = " For a match state with at least one non-ZERO pattern ID, the next bytes"] # [doc = " correspond to a sequence of 32-bit native endian encoded integers that"] # [doc = " represent each pattern ID, in order, that this match state represents."] # [doc = ""] # [doc = " After the pattern IDs (if any), NFA state IDs are delta encoded as"] # [doc = " varints.[1] The first NFA state ID is encoded as itself, and each"] # [doc = " subsequent NFA state ID is encoded as the difference between itself and the"] # [doc = " previous NFA state ID."] # [doc = ""] # [doc = " [1] - https://developers.google.com/protocol-buffers/docs/encoding#varints"] struct Repr < 'a > (& 'a [u8]) ;
    };
}

Repr!();